async function route(path: string, query: (id: number) => Promise<string>): Promise<string> {
  const segment = path.split("/").at(-1);
  if (!segment) {
    return "missing";
  }
  const id = Number(segment);
  if (!Number.isInteger(id)) {
    return "invalid";
  }
  const response = await query(id);
  return response.trim();
}

function flush(chunks: string[], append: (text: string) => void, commit: () => void): void {
  const header = "BEGIN";
  const payload = chunks
    .filter((chunk) => chunk.length > 0)
    .join(";");
  append(header);
  append(payload);
  // Commit the completed batch.
  commit();
}

async function retry(attempt, fallback) {
  const first = await attempt();
  if (first !== null) {
    return first;
  }
  const backup = await fallback();
  return backup;
}

function index(entries, report) {
  const byName = new Map();
  for (const [name, value] of entries) {
    const key = name.toLowerCase();
    byName.set(key, value);
  }
  const names = [...byName.keys()];
  names.sort();
  report(names);
  return byName;
}

def batches(values, width, emit):
    count = len(values)
    if width <= 0:
        raise ValueError("positive width required")
    for start in range(0, count, width):
        end = min(start + width, count)
        batch = values[start:end]
        emit(batch)
    return count

def resolve(records, identifier):
    record = records.get(identifier)
    if record is None:
        return "anonymous"
    first = record.get("first", "")
    last = record.get("last", "")
    # Empty components are omitted from the display name.
    return " ".join(
        part for part in (first, last) if part
    )

import java.io.IOException;
import java.io.Writer;
class Export {
    static int write(Writer target, String body) throws IOException {
        String cleaned = body.strip();
        if (cleaned.isEmpty()) {
            return 0;
        }
        String ending = System.lineSeparator();
        target.write(cleaned);
        target.write(ending);
        target.flush();
        return cleaned.length();
    }
}

class Search {
    static int firstLong(String[] words, int length) {
        int result = -1;
        for (int i = 0; i < words.length; i++) {
            String word = words[i];
            if (word.length() >= length) {
                result = i;
                break;
            }
        }
        return result;
    }
}

fn inspect(key: Option<&str>, output: &mut Vec<String>) -> bool {
    let Some(text) = key else {
        return false;
    };
    if text.is_empty() {
        return false;
    }
    let description = format!("key={}", text);
    output.push(description);
    return true;
}

fn lengths(words: &[&str]) -> (usize, usize) {
    let mut count = 0;
    let mut total = 0;
    for word in words {
        count += 1;
        total += word.len();
    }
    (
        count,
        total,
    )
}

fn publish(bytes: []const u8, offset: ?usize, send: *const fn ([]const u8) void) bool {
    const start = offset orelse return false;
    if (start >= bytes.len) {
        return false;
    }
    const selected = bytes[start..];
    send(selected);
    return true;
}

fn position(values: []const i32, wanted: i32) ?usize {
    const count = values.len;
    for (0..count) |index| {
        const value = values[index];
        if (value == wanted) {
            return index;
        }
    }
    // The requested value was absent.
    return null;
}

