func partition(values []int) ([]int, []int) {
    positive := make([]int, 0)
    negative := make([]int, 0)
    for _, value := range values {
        if value >= 0 {
            positive = append(positive, value)
        } else {
            negative = append(negative, value)
        }
    }
    return positive, negative
}

#include <algorithm>
#include <vector>
bool erase(std::vector<int>& values, int wanted) {
    const auto found = std::find(values.begin(), values.end(), wanted);
    if (found == values.end()) {
        return false;
    }
    const auto index = found - values.begin();
    values.erase(values.begin() + index);
    return true;
}

#include <numeric>
#include <vector>
double average(const std::vector<int>& values) {
    const auto count = values.size();
    if (count == 0) {
        return 0.0;
    }
    const auto total = std::accumulate(
        values.begin(), values.end(), 0.0,
        [](double sum, int value) { return sum + value; });
    return total / count;
}

using System;
public static class Input
{
    public static bool Accept(string text, Action<int> submit)
    {
        var parsed = int.TryParse(text, out var number);
        if (!parsed)
        {
            return false;
        }
        var normalized = Math.Abs(number);
        submit(normalized);
        return true;
    }
}

public static class Counts
{
    public static object Describe(string? text)
    {
        var length = text?.Length ?? 0;
        if (length == 0)
        {
            return new { Label = "empty", Size = 0 };
        }
        var result = new
        {
            Label = "content",
            Size = length
        };
        return result;
    }
}

fun remember(values: MutableMap<String, String>, key: String, load: () -> String?): Boolean {
    val loaded = load()
    if (loaded == null) {
        return false
    }
    val cleaned = loaded.trim()
    values.put(key, cleaned)
    return true
}

fun names(entries: Map<String, Int>): String {
    val active = entries.filterValues { it > 0 }
    if (active.isEmpty()) {
        return "none"
    }
    val result = active.keys
        .sorted()
        .joinToString(", ")
    // Present the stable ordering to the caller.
    return result
}

func save(value: String?, store: (String) -> Void) -> Bool {
    let missing = value == nil
    if missing {
        return false
    }
    if let text = value {
        let wrapped = "[" + text + "]"
        store(wrapped)
    }
    return true
}

func total(records: [String: Int]) -> (Int, Int) {
    var count = 0
    var sum = 0
    for (_, value) in records {
        count += 1
        sum += value
    }
    return (
        count,
        sum
    )
}
